    vKeys[g].forEach(k => r.vit[k] = d[k]); r.vitAt = now(); const add = (m, v) => { if (v === '' || v == null) return; const s = r.trend[m]; if (s.length && s[s.length - 1][0] === '20 Oct') s[s.length - 1][1] = v; else s.push(['20 Oct', v]); };
